def set_font(run, bold=False, italic=False):
    run.font.name = FONT
    run.font.size = SIZE
    run.bold = bold
    run.italic = italic
    run._element.rPr.rFonts.set(qn("w:eastAsia"), FONT)


def build(path):
    doc = Document()
    for section in doc.sections:
        section.page_height = Cm(29.7)
        section.page_width = Cm(21.0)
        section.top_margin = Cm(2)
        section.bottom_margin = Cm(2)
        section.left_margin = Cm(2.5)
        section.right_margin = Cm(1.5)

    normal = doc.styles["Normal"]
    normal.font.name = FONT
    normal.font.size = SIZE
    normal.element.rPr.rFonts.set(qn("w:eastAsia"), FONT)

    for kind, text in CONTENT:
        par = doc.add_paragraph()
        fmt = par.paragraph_format
        fmt.line_spacing = LINE_SPACING
        fmt.space_before = Pt(0)
        fmt.space_after = Pt(0)
        if kind == P:
            fmt.first_line_indent = Cm(1.25)
            par.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
            head, sep, tail = text.partition(". ")
            if head in ("Аннотация", "Abstract") or text.startswith(("Ключевые слова:", "Keywords:")):
                label, rest = (head + ".", " " + tail) if sep and head in ("Аннотация", "Abstract") else text.split(":", 1)
                if not label.endswith("."):
                    label += ":"
                set_font(par.add_run(label), bold=True)
                set_font(par.add_run(rest), italic=False)
            else:
                set_font(par.add_run(text))
        elif kind == H:
            fmt.space_before = Pt(6)
            fmt.keep_with_next = True
            par.alignment = WD_ALIGN_PARAGRAPH.CENTER
            set_font(par.add_run(text), bold=True)
        elif kind == C:
            fmt.space_before = Pt(6)
            fmt.space_after = Pt(6)
            par.alignment = WD_ALIGN_PARAGRAPH.CENTER
            set_font(par.add_run(text), bold=True)
        elif kind == L:
            par.alignment = WD_ALIGN_PARAGRAPH.RIGHT if not text.startswith("УДК") else WD_ALIGN_PARAGRAPH.LEFT
            set_font(par.add_run(text), italic=not text.startswith("УДК"))
        elif kind == R:
            par.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
            fmt.first_line_indent = Cm(1.25)
            set_font(par.add_run(text))
    doc.save(path)


if __name__ == "__main__":
    import os

    out = os.path.join(os.path.dirname(os.path.abspath(__file__)), "statya_nezakonnoe_obogashchenie.docx")
    build(out)
    total = sum(len(t) for _, t in CONTENT)
    print(out, "characters:", total)
